import json
import random
import string
from typing import List, Tuple

# Generator for configuration value strings used across various APIs expecting const char*.
# We aim to produce valid, well-formed text inputs that exercise diverse code paths:
# - JSON objects/arrays with common option names
# - Key=Value lines (INI-like)
# - Simple scalar strings (paths, addresses, flags)
# - ADB-like configs (device serials, tcpip endpoints)
# - Mixed-length variations while keeping under 4096 bytes
# The fuzzer stubs call FUZZ_PARAM_STR() multiple times per invocation; our single buffer
# will be split by the harness into independent random blobs. Therefore we include clear
# separation via null terminators and varied entries, each being a standalone valid string.

MAX_TOTAL = 4096

COMMON_KEYS = [
    "enable",
    "disable",
    "timeout_ms",
    "retries",
    "log_level",
    "path",
    "adb_path",
    "address",
    "config",
    "mode",
    "profile",
    "uuid",
    "extras",
    "resolution",
    "width",
    "height",
    "x",
    "y",
    "block",
]

LOG_LEVELS = ["trace", "debug", "info", "warn", "error", "fatal"]
MODES = ["default", "safe", "fast", "compat", "experimental"]
BOOL_STR = ["true", "false", "1", "0"]

PATH_FRAG = ["/usr/local/share/asst", "/var/tmp/asst", ".asst", "C:/asst", "..", "/tmp"]
DEVICE_ADDRS = [
    "127.0.0.1:5555",
    "localhost:5037",
    "192.168.0.2:5555",
    "usb:",
    "emulator-5554",
]

# Some common task-like types for AsstAppendTask
TASK_TYPES = [
    "click",
    "screencap",
    "back_to_home",
    "connect",
    "disconnect",
    "wait",
    "set_option",
]


def _rand_uuid(rng: random.Random) -> str:
    def rnd(n):
        return ''.join(rng.choice('0123456789abcdef') for _ in range(n))
    return f"{rnd(8)}-{rnd(4)}-{rnd(4)}-{rnd(4)}-{rnd(12)}"


def _json_value(rng: random.Random):
    choice = rng.random()
    if choice < 0.2:
        return rng.randint(0, 100000)
    if choice < 0.4:
        return (rng.random() < 0.5)
    if choice < 0.7:
        return rng.choice(["", rng.choice(LOG_LEVELS), rng.choice(MODES), _rand_uuid(rng)])
    if choice < 0.85:
        # small array
        return [ _json_value(rng) for _ in range(rng.randint(1, 4)) ]
    # small object
    obj = {}
    for _ in range(rng.randint(1, 4)):
        obj[rng.choice(COMMON_KEYS)] = _json_value(rng)
    return obj


def gen_json_config(rng: random.Random) -> str:
    cfg = {}
    # include a few standard fields
    cfg["log_level"] = rng.choice(LOG_LEVELS)
    cfg["enable"] = rng.choice([True, False])
    cfg["timeout_ms"] = rng.choice([0, 1, 10, 100, 1000, 5000, 20000])
    cfg["retries"] = rng.randint(0, 10)
    if rng.random() < 0.7:
        cfg["path"] = rng.choice(PATH_FRAG)
    if rng.random() < 0.6:
        cfg["address"] = rng.choice(DEVICE_ADDRS)
    if rng.random() < 0.5:
        cfg["uuid"] = _rand_uuid(rng)
    # add a few random keys
    for _ in range(rng.randint(0, 4)):
        cfg[rng.choice(COMMON_KEYS)] = _json_value(rng)
    return json.dumps(cfg, separators=(",", ":"))


def gen_kv_config(rng: random.Random) -> str:
    # INI-like multiline
    lines: List[str] = []
    n = rng.randint(3, 10)
    for _ in range(n):
        k = rng.choice(COMMON_KEYS)
        v_choice = rng.random()
        if v_choice < 0.25:
            v = str(rng.randint(0, 10000))
        elif v_choice < 0.5:
            v = rng.choice(BOOL_STR)
        elif v_choice < 0.75:
            v = rng.choice([rng.choice(LOG_LEVELS), rng.choice(MODES)])
        else:
            v = rng.choice([rng.choice(PATH_FRAG), rng.choice(DEVICE_ADDRS), _rand_uuid(rng)])
        lines.append(f"{k}={v}")
    return "\n".join(lines)


def gen_scalar(rng: random.Random) -> str:
    choices = []
    # simple items that may be used by APIs expecting single strings
    choices += LOG_LEVELS
    choices += MODES
    choices += PATH_FRAG
    choices += DEVICE_ADDRS
    choices += ["--verbose", "--quiet", "--no-cache", "--reset"]
    if rng.random() < 0.5:
        choices.append(_rand_uuid(rng))
    return rng.choice(choices)


def gen_task_params(rng: random.Random) -> str:
    # plausible task params in JSON
    t = rng.choice(TASK_TYPES)
    obj = {"type": t}
    if t == "click":
        obj.update({"x": rng.randint(0, 1920), "y": rng.randint(0, 1080), "block": rng.choice([True, False])})
    elif t == "wait":
        obj.update({"timeout_ms": rng.choice([100, 500, 1000, 5000])})
    elif t == "screencap":
        obj.update({"format": rng.choice(["rgb", "bgr", "png"])})
    elif t == "set_option":
        obj.update({"key": rng.choice(COMMON_KEYS), "value": gen_scalar(rng)})
    elif t == "connect":
        obj.update({"adb_path": rng.choice(PATH_FRAG), "address": rng.choice(DEVICE_ADDRS), "block": rng.choice([True, False])})
    return json.dumps(obj, separators=(",", ":"))


def gen_connection_extras(rng: random.Random) -> Tuple[str, str]:
    name = rng.choice(["default", "wifi", "usb", "emulator", "staging", "prod"]) + (
        "-" + rng.choice(["a", "b", "c", "x"]) if rng.random() < 0.3 else ""
    )
    extras_obj = {
        "mtu": rng.choice([1200, 1350, 1500]),
        "keepalive_s": rng.choice([0, 5, 15, 60]),
        "compression": rng.choice(["none", "lz4", "zstd"]),
    }
    if rng.random() < 0.5:
        extras_obj["auth"] = {"token": _rand_uuid(rng)}
    return name, json.dumps(extras_obj, separators=(",", ":"))


def gen_static_option_pair(rng: random.Random) -> str:
    # Without knowing numeric keys, provide a value string that plausibly maps to many keys
    kind = rng.random()
    if kind < 0.4:
        return gen_json_config(rng)
    if kind < 0.7:
        return gen_kv_config(rng)
    return gen_scalar(rng)


def pack_c_strings(strings: List[str]) -> bytes:
    # Join as null-terminated C strings; ensure total length under MAX_TOTAL
    out = bytearray()
    for s in strings:
        b = s.encode('utf-8', errors='strict') + b"\x00"
        if len(out) + len(b) > MAX_TOTAL:
            break
        out += b
    # Ensure at least one terminator present
    if not out:
        out = bytearray(b"\x00")
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Compose a set of strings in the order that helps cover various stubs:
    strings: List[str] = []

    # For AsstSetStaticOption value
    strings.append(gen_static_option_pair(rng))

    # For AsstSetConnectionExtras: name and extras
    name, extras = gen_connection_extras(rng)
    strings.append(name)
    strings.append(extras)

    # For AsstSetInstanceOption value
    strings.append(gen_static_option_pair(rng))

    # For AsstConnect / AsstAsyncConnect: adb_path, address, config
    strings.append(rng.choice(PATH_FRAG))            # adb_path
    strings.append(rng.choice(DEVICE_ADDRS))         # address
    strings.append(gen_json_config(rng))             # config

    # For AsstAppendTask: type and params
    strings.append(rng.choice(TASK_TYPES))           # type
    strings.append(gen_task_params(rng))             # params

    # For AsstSetTaskParams: params
    strings.append(gen_task_params(rng))

    # Additional scalars to increase pool variety for FUZZ_PARAM_STR calls
    for _ in range(rng.randint(2, 6)):
        choice = rng.random()
        if choice < 0.34:
            strings.append(gen_scalar(rng))
        elif choice < 0.67:
            strings.append(gen_kv_config(rng))
        else:
            strings.append(gen_json_config(rng))

    return pack_c_strings(strings)

import random
import struct
from typing import List

# This generator produces valid null-terminated strings intended for the
# AsstConnect/AsstAsyncConnect fuzzer stubs. The fuzzer consumes three
# FUZZ_PARAM_STR values: adb_path, address, config. We pack them as three
# consecutive C strings (null-terminated) in one buffer, which the harness
# will then slice to feed FUZZ_PARAM_STR.
#
# Address strings cover multiple valid formats:
# - IPv4
# - IPv4 with port (host:port)
# - Hostname
# - Hostname with port
# - Loopback variants
# - Android ADB device selectors (serials, tcpip forms)
# - IPv6 (with and without brackets, and with port)
#
# ADB path strings include common executable names and plausible absolute/relative paths.
# Config strings use key=value;key=value forms and JSON-like content, both null-terminated.

MAX_TOTAL = 4096

ADB_BASENAMES = [
    "adb",
    "adb.exe",
    "platform-tools/adb",
    "tools/adb",
]

ADB_PREFIXES = [
    "/usr/bin/",
    "/usr/local/bin/",
    "/opt/android-sdk/platform-tools/",
    "C:/Android/platform-tools/",
    "./",
    "../bin/",
    "",
]

HOST_LABELS = [
    "localhost", "example", "device", "phone", "tablet", "emulator",
    "android", "test", "staging", "prod", "edge"
]

CONFIG_KEYS = [
    "transport", "serial", "timeout_ms", "auth", "reconnect", "ssl",
    "bufsize", "compression", "heartbeat_ms", "log_level", "retries"
]

LOG_LEVELS = ["trace", "debug", "info", "warn", "error"]

HEX_DIGITS = "0123456789abcdef"


def _rand_ipv4(r: random.Random) -> str:
    # Avoid 0/255 in host where possible but still permit edge values occasionally
    octets = []
    for i in range(4):
        if r.random() < 0.15:
            octets.append(str(r.randint(0, 255)))
        else:
            octets.append(str(r.randint(1, 254)))
    return ".".join(octets)


def _rand_port(r: random.Random) -> int:
    # Favor typical ports for adb and services, but include random
    choices = [5037, 5555, 22, 80, 443, r.randint(1, 65535)]
    return r.choice(choices)


def _rand_hostname(r: random.Random) -> str:
    # Labels 1-4, each 1-12 chars, alnum with hyphens, not starting/ending with hyphen
    nlabels = r.randint(1, 4)
    labels = []
    for _ in range(nlabels):
        length = r.randint(1, 12)
        s = []
        for i in range(length):
            c = r.choice("abcdefghijklmnopqrstuvwxyz0123456789-")
            s.append(c)
        # Fix start/end hyphen
        if s[0] == '-':
            s[0] = r.choice("abcdefghijklmnopqrstuvwxyz0123456789")
        if s[-1] == '-':
            s[-1] = r.choice("abcdefghijklmnopqrstuvwxyz0123456789")
        labels.append("".join(s))
    # Optionally add TLD
    if r.random() < 0.7:
        labels.append(r.choice(["local", "lan", "example", "test", "corp", "com", "net"]))
    return ".".join(labels)


def _rand_ipv6(r: random.Random) -> str:
    # Generate full 8 hextets, possibly compress with ::
    hextets = ["%x" % r.randint(0, 0xFFFF) for _ in range(8)]
    # Optionally introduce zero runs to allow nicer compression
    if r.random() < 0.5:
        i = r.randint(0, 6)
        zlen = r.randint(2, min(6, 8 - i))
        for k in range(i, i + zlen):
            hextets[k] = '0'
    addr = ":".join(hextets)
    # Compress the longest run of zeros
    # Simple compression: find any run of consecutive '0' and replace with '' once
    best_i = -1
    best_len = 0
    cur_i = -1
    cur_len = 0
    for i, h in enumerate(hextets):
        if h == '0':
            if cur_i == -1:
                cur_i = i
                cur_len = 1
            else:
                cur_len += 1
        else:
            if cur_len > best_len:
                best_len = cur_len
                best_i = cur_i
            cur_i = -1
            cur_len = 0
    if cur_len > best_len:
        best_len = cur_len
        best_i = cur_i
    if best_len >= 2:
        comp = hextets[:best_i] + [''] + hextets[best_i + best_len:]
        # Handle edge cases for leading/trailing compression
        if best_i == 0:
            addr = "::" + ":".join(comp[1:])
        elif best_i + best_len == 8:
            addr = ":".join(comp[:-1]) + "::"
        else:
            addr = ":".join(comp)
            addr = addr.replace(":::", "::")
    return addr


def _rand_adb_path(r: random.Random) -> str:
    if r.random() < 0.4:
        # Absolute or common path
        return r.choice(ADB_PREFIXES) + r.choice(ADB_BASENAMES)
    # Custom-looking path
    parts = [
        r.choice(["/usr", "/opt", "/home/user", "C:/Tools", "./bin", "./", "../tools"]),
        r.choice(["android", "sdk", "platform-tools", "tools", "bin", "usr"]),
        "adb" + (".exe" if r.random() < 0.3 else ""),
    ]
    # Join with appropriate separators heuristically
    sep = "/"
    path = sep.join(p.strip("/") for p in parts if p)
    if path.startswith("C:"):
        path = path.replace("/", "/")
    return path


def _rand_address(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.15:
        return "localhost"
    if choice < 0.35:
        return _rand_ipv4(r)
    if choice < 0.55:
        return f"{_rand_ipv4(r)}:{_rand_port(r)}"
    if choice < 0.70:
        return _rand_hostname(r)
    if choice < 0.85:
        return f"{_rand_hostname(r)}:{_rand_port(r)}"
    # IPv6 variants
    if choice < 0.93:
        return _rand_ipv6(r)
    # Bracketed IPv6 with port
    addr = _rand_ipv6(r)
    return f"[{addr}]:{_rand_port(r)}"


def _rand_adb_serial(r: random.Random) -> str:
    # Examples: emulator-5554, 0123456789ABCDEF, 192.168.0.10:5555
    pick = r.random()
    if pick < 0.35:
        return f"emulator-{_rand_port(r)}"
    if pick < 0.70:
        # Hex serial length 8-16
        length = r.randint(8, 16)
        return ''.join(r.choice('0123456789ABCDEF') for _ in range(length))
    return f"{_rand_ipv4(r)}:{_rand_port(r)}"


def _rand_config_pairs(r: random.Random) -> str:
    n = r.randint(1, 6)
    used = set()
    parts: List[str] = []
    for _ in range(n):
        key = r.choice(CONFIG_KEYS)
        if key in used and r.random() < 0.6:
            key = f"{key}{r.randint(2,9)}"
        used.add(key)
        if key in ("timeout_ms", "heartbeat_ms", "retries", "bufsize"):
            val = str(r.randint(0, 20000))
        elif key in ("transport",):
            val = r.choice(["usb", "local", "any", "tcpip"])
        elif key in ("ssl", "compression", "reconnect"):
            val = r.choice(["0", "1", "true", "false"])
        elif key == "serial":
            val = _rand_adb_serial(r)
        elif key == "log_level":
            val = r.choice(LOG_LEVELS)
        else:
            val = ''.join(r.choice('abcdefghijklmnopqrstuvwxyz0123456789_-') for _ in range(r.randint(3, 12)))
        parts.append(f"{key}={val}")
    return ";".join(parts)


def _rand_config_json(r: random.Random) -> str:
    # JSON-like but simple; keys from CONFIG_KEYS
    n = r.randint(2, 7)
    keys = r.sample(CONFIG_KEYS, k=min(n, len(CONFIG_KEYS)))
    items = []
    for k in keys:
        if k in ("timeout_ms", "heartbeat_ms", "retries", "bufsize"):
            v = str(r.randint(0, 20000))
        elif k in ("ssl", "compression", "reconnect"):
            v = r.choice(["true", "false"])
        elif k == "serial":
            v = '"' + _rand_adb_serial(r) + '"'
        elif k == "log_level":
            v = '"' + r.choice(LOG_LEVELS) + '"'
        elif k == "transport":
            v = '"' + r.choice(["usb", "local", "any", "tcpip"]) + '"'
        else:
            v = '"' + ''.join(r.choice('abcdefghijklmnopqrstuvwxyz0123456789_-') for _ in range(r.randint(3, 12))) + '"'
        items.append(f'"{k}": {v}')
    return "{" + ", ".join(items) + "}"


def _cstr(b: bytes) -> bytes:
    # Ensure single terminating null and no internal nulls; if internal nulls appear,
    # truncate at first null to keep validity as typical C-string expectations.
    nul = b.find(b"\x00")
    if nul != -1:
        b = b[:nul]
    return b + b"\x00"


def _pick_config(r: random.Random) -> str:
    if r.random() < 0.5:
        return _rand_config_pairs(r)
    return _rand_config_json(r)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Compose three valid strings: adb_path, address, config
    adb_path = _rand_adb_path(r)
    # Occasionally provide an empty adb_path to allow library defaults to kick in
    if r.random() < 0.15:
        adb_path = ""

    # Address: include diversified formats
    address = _rand_address(r)
    # Occasionally emulate ADB selectors like serial@host:port or direct serial
    if r.random() < 0.25:
        if r.random() < 0.5:
            address = _rand_adb_serial(r)
        else:
            address = f"{_rand_adb_serial(r)}@{_rand_ipv4(r)}:{_rand_port(r)}"

    config = _pick_config(r)

    parts = [
        _cstr(adb_path.encode('utf-8', errors='ignore')),
        _cstr(address.encode('utf-8', errors='ignore')),
        _cstr(config.encode('utf-8', errors='ignore')),
    ]

    out = b"".join(parts)
    if len(out) > MAX_TOTAL:
        out = out[:MAX_TOTAL]
        # Ensure it still ends with a null terminator; add if truncated in the middle of a string
        if not out.endswith(b"\x00"):
            # Trim to make room for one null
            out = out[:-1] + b"\x00"
    return out
